example:
// Jenkinsfile at repo root (Declarative)
pipeline {
  agent any
  stages {
    stage('Build') { steps { sh 'make' } }
    stage('Test')  { steps { sh 'make test' } }
  }
}

// Declarative: fixed structure
pipeline {
  agent any
  stages { stage('Build') { steps { sh 'make' } } }
}

// Scripted: free-form Groovy
node {
  stage('Build') { if (env.BRANCH_NAME == 'main') { sh 'make' } }
}

pipeline {
  agent { label 'linux && docker' }   // run on a matching node
  stages {
    stage('Build') {
      agent { docker { image 'maven:3.9' } }  // per-stage container agent
      steps { sh 'mvn -B package' }
    }
  }
}

// Both styles still work in current Jenkins
// Scripted:
node('linux') {
  checkout scm
  sh './gradlew build'
}
// Declarative can also embed Scripted via script { } blocks

# merged to main while still incomplete, hidden behind a flag
if feature_flags.enabled("new-checkout", user):
    return render_new_checkout()
return render_legacy_checkout()  # default until flag flips

# LaunchDarkly-style flag check; flipping the flag needs no deploy
if ld_client.variation("new-search", user, False):
    results = new_search(query)
else:
    results = legacy_search(query)

